 function paint(){log.replaceChildren();const thread=current();if(!thread?.messages.length){const welcome=document.createElement('div');welcome.className='agentWelcome';const icon=document.createElement('span');icon.textContent='✧';const title=document.createElement('h2');title.textContent='من الفكرة إلى ملفك';const subtitle=document.createElement('p');subtitle.textContent='أرفق ملفك هنا، وقل لي وش تبي تسوي.';welcome.append(icon,title,subtitle);const chips=document.createElement('div');chips.className='agentSuggestions';for(const text of ['استخرج النص من الصورة','قص السكتات وحسّن الصوت','سوِّ لي صورة حسب وصفي']){const b=document.createElement('button');b.type='button';b.textContent=text;b.onclick=()=>{input.value=text;input.focus();};chips.append(b);}welcome.append(chips);log.append(welcome);}else thread.messages.forEach(append);if(thread?.choiceRequest)paintChoices();badge();scroll();}
