 function isMotionRevision(text){const thread=current(),last=(thread?.messages||[]).filter(m=>m.result).at(-1);if(MadarConversation.motionFeedback(text,{project:thread?.motionProject,relevant:!last||!!last.motionProject}))return true;text=text.normalize('NFKC').replace(/[\u064b-\u065f\u0670]/g,'');if(!current()?.motionProject||/(?:موشن|إعلان|اعلان|فيديو|مشروع)\s+جديد/.test(text))return false;if(/^(?:(?:كمل|أكمل|اكمل|تابع)[ ،]*)?(?:بدون|تجاهل|اترك)\s+الرابط/.test(text)&&/تعذرت قراءة الصفحة|أرسل رابط صفحة عامة/.test(current().messages.filter(m=>m.role==='assistant').at(-1)?.text||''))return true;if(/الصورة|للصورة|ملف PDF|التسجيل/.test(text)&&!/المشهد|الموشن|الإعلان|الاعلان|الفيديو السابق/.test(text))return false;return /^(?:طيب[ ،]*)?(?:عدل|عدّل|غير|غيّر|خلي|خلّ|أضف|اضف|بدل|بدّل|قلل|قصّر|طوّل|احذف المشهد)/.test(text)&&/مشهد|الإعلان|الاعلان|الموشن|النهاية|النهايه|البداية|العنوان|التعليق|الخلفية|الألوان|الالوان|الخط|النص/.test(text)||/^(?:أعد|اعد|سوي|سو)\s+(?:لي\s+)?(?:نفس\s+)?(?:الموشن|الإعلان|الاعلان|الفيديو السابق)/.test(text);}
