 function motionFollowup(text){const t=motionWords(text),end='[.!؟\\s]*$',reconnect=/^(?:طيب[ ،]*)?(?:اعد|عيد|جدد)\s+(?:الاتصال|الربط)(?:\s+(?:ب(?:ال)?\s*)?(?:colab|كولاب|الكولاب))?(?:[ ،]*و?\s*ارسل(?:ه|لي|ي)?\s*(?:لي\s*)?(?:الفيديو|المقطع|النتيجه)?(?:\s+جاهز(?:ا)?)?)?[.!؟\s]*$/i.test(t);return {retry:/^(?:ابدا|ابدء|يلا)[.!؟\s]*$/.test(t)||reconnect||new RegExp('^(?:طيب[ ،]*)?(?:(?:جرب|حاول|عيد|اعد|كرر|اعاده)(?:\\s+(?:من جديد|مره ثانيه|المحاوله|الطلب|الموشن(?: جرافيك)?|الاعلان))?|(?:اكمل|كمل|تابع|استكمل)(?:\\s+(?:معالجه\\s+)?(?:طلب\\s+)?(?:الموشن(?: جرافيك)?|موشن جرافيك|الاعلان|الطلب|الفيديو))?|(?:لا\\s+اريد|ما\\s+ابي)\\s+(?:اي\\s+)?اضافه[ ،]*\\s*(?:ارسله?\\s*(?:لي)?)?|ارسله?\\s+لي(?:\\s+(?:بدون اضافات|كما هو))?)'+end).test(t),question:/^(?:(?:ليش|لماذا)(?:\s+(?:وقف|فشل|ما\s*(?:زبط|ضبط|اشتغل)))?|(?:وش|اش|ايش|ما هي)\s+(?:صار|المشكله|السبب|يعني كذا)(?:\s+بالضبط)?|ما\s*(?:زبط|ضبط|اشتغل|اشتغلت))[.!?؟\s]*$/.test(t)};}
 function otherFileRequest(text){return /^(?:حول|حوّل|اضغط|قص|اقص|استخرج|ادمج|ترجم|نظف|نقّ|حسن|حسّن|ارفع|خفض|احذف|أزل|ازل|افصل|افتح|حمّل|حمل|نزّل|نزل|ارسم|صمم|صمّم|أضف|اضف)(?=$|[\s،])/.test(text)&&/صور|صورة|فيديو|مقطع|ملف|PDF|صوت|تسجيل|نص|مستند|موسيقى|خلفية|QR/i.test(text)||/^(?:عدل|عدّل|غير|غيّر).*الصورة/.test(text);}
 function recoverMotionReply(text,record){const thread=current();if(!thread?.motionFailure||!thread.motionRetry||thread.motionPending||thread.motionPauseReason==='file'&&!/(?:الموشن|الإعلان|الاعلان)/.test(text))return false;const chosen=motionReplyVoice(text),{retry,question}=motionFollowup(text);if(!chosen&&!retry&&!question)return false;if(record)line(text,'user');input.value='';if(chosen||retry){const original=thread.motionRetry,voice=chosen||$('agentMotionVoice').value||original.voice;if(chosen){$('agentMotionVoice').value=voice;thread.motionVoice=voice;thread.motionVoiceSelected=true;}if(voice!==original.voice){if(original.setup)thread.motionSetup={...original.setup,voice,confirmed:true};startMotion(original.prompt,{voice,previous:original.previous||'',configured:true});}else{const retryRequest={...original,voice};delete retryRequest.resumeProject;if(thread.motionResumeProject)retryRequest.resumeProject=thread.motionResumeProject;launchMotion(retryRequest);}return true;}line(thread.motionFailure+' طلبك السابق محفوظ؛ اكتب «أعد المحاولة» للاستكمال.');return true;}
