 window.addEventListener('agentLinkReady',()=>{if(!agentDownload||job?.thread!==active||job?.tool!=='downloadLink')return;const settings=agentDownload;agentDownload=null;$('linkMode').value=settings.mode;const values=[...$('linkQuality').options].map(o=>Number(o.value));const highest=Math.max(0,...values);if(highest)$('linkQuality').querySelector('option[value="0"]').textContent='أعلى جودة متاحة ('+highest+'p)';const exact=values.includes(settings.height);$('linkQuality').value=String(exact?settings.height:0);if(settings.explicitQuality&&exact){line('التحميل: '+$('linkQuality').selectedOptions[0].textContent);startExport();return;}clearJob();setBusy(false);busy(false);task('');$('sheet').hidden=true;askChoices({kind:'download',url:$('linkUrl').value,title:settings.explicitQuality?'الدقة المطلوبة غير متاحة؛ اختر من الجودات الفعلية':'بأي صيغة وجودة تبي المقطع؟',fields:[{name:'linkMode',label:'نوع التحميل',type:'select',value:settings.mode,options:[...$('linkMode').options].map(o=>[o.value,o.textContent])},{name:'linkQuality',label:'الجودات المتاحة لهذا الرابط',type:'select',value:'0',options:[...$('linkQuality').options].map(o=>[o.value,o.textContent])}]});});
